 document.addEventListener('keydown',e=>{if(db.settings.keyboardShortcuts===false&&e.key!=='Escape')return;if(e.key==='Escape'){const wasBulk=!!$('#bulkGroup');closeModal();if(wasBulk)exitBulkSelectionMode();$('#sidebar').classList.remove('open');return}if(e.target.matches('input,textarea,select,[contenteditable="true"]'))return;if(e.key==='f'||e.key==='F'){if(!$('#playerDock').classList.contains('hidden')){e.preventDefault();const v=$('#videoPlayer');if(v.requestFullscreen)v.requestFullscreen().catch(()=>{});else TesitoPlayer.fullscreen()}return}if(e.key==='m'||e.key==='M'){if(!$('#playerDock').classList.contains('hidden'))$('#unmuteBtn').click();return}if(e.code==='Space'&&!$('#playerDock').classList.contains('hidden')){e.preventDefault();const v=$('#videoPlayer');if(v.paused)v.play().catch(()=>{});else v.pause();return}if(e.key==='ArrowDown'||e.key==='ArrowUp'){if($('#playerDock').classList.contains('hidden'))return;e.preventDefault();const ch=allChannels();if(!ch.length)return;let i=ch.findIndex(c=>c.id===activeChannelId);i=(i+(e.key==='ArrowDown'?1:-1)+ch.length)%ch.length;playChannel(ch[i].id)}});
 $('#modalClose').addEventListener('click',()=>{const wasBulk=!!$('#bulkGroup');closeModal();if(wasBulk)exitBulkSelectionMode()});$('#modalBackdrop').addEventListener('click',e=>{if(e.target===$('#modalBackdrop')){const wasBulk=!!$('#bulkGroup');closeModal();if(wasBulk)exitBulkSelectionMode()}});$('#playlistFileInput').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{const text=await file.text();if(selectedPlaylist){const p=db.playlists.find(p=>p.id===selectedPlaylist);if(p){const incoming=TesitoPlaylist.parse(text,file.name.replace(/\.(m3u8?|txt)$/i,''));if(!incoming.channels.length){toast('No se encontraron canales válidos.','error');return}p.channels.push(...incoming.channels);save();refresh();renderEditorWorkspace(p.id);toast(`${incoming.channels.length} canales añadidos.`,'success');selectedPlaylist=null;return}}importText(text,file.name.replace(/\.(m3u8?|txt)$/i,''))}catch(err){toast('No se pudo leer el archivo.','error')}});
