 $('#videoFileInput').addEventListener('change',e=>{const file=e.target.files?.[0];e.target.value='';if(file){$('#playerDock').classList.remove('hidden');$('#nowTitle').textContent=file.name;$('#nowSubtitle').textContent='Archivo local';$('#overlayTitle').textContent=file.name;$('#overlayMessage').textContent='Preparando archivo…';TesitoPlayer.localFile(file)}});
 document.addEventListener('submit',async e=>{if(e.target.id==='urlImportForm'){e.preventDefault();const url=$('#playlistUrl').value.trim(),name=$('#urlListName').value.trim();if(!/^https?:\/\//i.test(url)){toast('Usa una URL http:// o https:// válida.','error');return}const btn=e.submitter;btn.disabled=true;btn.textContent='Importando…';try{const res=await fetch(url,{mode:'cors'});if(!res.ok)throw new Error('HTTP '+res.status);const text=await res.text();if(!text.trim().startsWith('#EXTM3U')&&!text.includes('#EXTINF'))throw new Error('El contenido no parece M3U');if(!importText(text,name||'Lista remota'))throw new Error('No se detectaron canales')}catch(err){btn.disabled=false;btn.textContent='Importar lista';toast('No se pudo importar la lista. Comprueba la URL y que el servidor permita CORS; no podemos saltarnos esa restricción desde GitHub Pages.','error')}}else if(e.target.id==='pasteImportForm'){e.preventDefault();const text=$('#m3uText').value;importText(text,$('#pasteListName').value.trim()||'Lista pegada')}});
 let editorSearchFrame=0;$('#editorWorkspace').addEventListener('input',e=>{const row=e.target.closest('#editorRows tr');if(row&&e.target.id!=='editorChannelSearch')row.dataset.searchDirty='1';if(e.target.id==='editorChannelSearch'){if(editorSearchFrame)cancelAnimationFrame(editorSearchFrame);editorSearchFrame=requestAnimationFrame(()=>{editorSearchFrame=0;applyEditorSearch()})}});
